  ('e-005', 1, 'english', 'english.grammar', 'review', '{"blueprint_version":"onet-p6-2569-draft","item_type":"single_choice","review_status":"review","version":1,"source_refs":["original:prototype-2569-11"],"id":"e-005","subject":"english","indicator":"ต-TBD-ไวยากรณ์","skill_id":"english.grammar","difficulty":1,"variant_family_id":"fam.eng.present_simple_s","stem":"Mali ______ to the library every Saturday.","options":[{"id":"a","text":"go"},{"id":"b","text":"goes"},{"id":"c","text":"going"},{"id":"d","text":"gone"}],"answer_key":"b","explanation":"ประธานเอกพจน์บุรุษที่ 3 (Mali) กับเหตุการณ์ที่ทำเป็นประจำ ใช้กริยาเติม -es → goes","distractor_rationale":{"a":"ใช้กับ I/you/we/they","c":"ต้องมี is นำหน้า","d":"ต้องมี has นำหน้า"}}'::jsonb),
