  ('s-002', 1, 'science', 'science.data_reading', 'review', '{"blueprint_version":"onet-p6-2569-draft","item_type":"single_choice","review_status":"review","version":1,"source_refs":["original:prototype-2569-11"],"id":"s-002","subject":"science","indicator":"ว-TBD-แปลความหมายข้อมูล","skill_id":"science.data_reading","difficulty":2,"variant_family_id":"fam.sci.table_growth","stem":"จากตาราง ข้อสรุปใดถูกต้องที่สุด","stimulus":{"kind":"table","caption":"ความสูงของต้นกล้า (เซนติเมตร)","headers":["วันที่","วางที่มีแสง","วางในที่มืด"],"rows":[["1","2","2"],["3","4","3"],["5","7","3"]]},"options":[{"id":"a","text":"ต้นกล้าในที่มืดสูงขึ้นเร็วกว่า"},{"id":"b","text":"ต้นกล้าที่ได้รับแสงสูงขึ้นมากกว่าในช่วง 5 วัน"},{"id":"c","text":"ต้นกล้าทั้งสองกลุ่มสูงเท่ากันทุกวัน"},{"id":"d","text":"แสงทำให้ต้นกล้าเตี้ยลง"}],"answer_key":"b","explanation":"กลุ่มที่มีแสงสูงจาก 2 เป็น 7 ซม. ส่วนกลุ่มในที่มืดสูงจาก 2 เป็น 3 ซม.","distractor_rationale":{"a":"ในที่มืดสูงขึ้นเพียง 1 ซม.","c":"เท่ากันเฉพาะวันที่ 1","d":"ข้อมูลแสดงตรงกันข้าม"}}'::jsonb),
